CREATE TABLE public.painel_uploads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  criado_em timestamptz NOT NULL DEFAULT now(),
  rotulo text NOT NULL,
  fonte text,
  dados jsonb NOT NULL
);
GRANT SELECT, INSERT ON public.painel_uploads TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.painel_uploads TO authenticated;
GRANT ALL ON public.painel_uploads TO service_role;
ALTER TABLE public.painel_uploads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "painel_leitura_publica" ON public.painel_uploads FOR SELECT USING (true);
CREATE POLICY "painel_envio_publico" ON public.painel_uploads FOR INSERT WITH CHECK (true);
CREATE INDEX painel_uploads_criado_em_idx ON public.painel_uploads (criado_em DESC);
